import { describe, expect, test } from "bun:test";

import { transformNapiLoader } from "../scripts/napi-loader-transform.mjs";

const generatedLoader = `// prettier-ignore
/* eslint-disable */
// @ts-nocheck
/* auto-generated by NAPI-RS */
const loadErrors = []
nativeBinding = requireNative()
error.cause = previous
error.cause = createLoadErrorChain(wasiBindingErrors)
error.cause = createLoadErrorChain(loadErrors)
    throw error
`;

describe("NAPI loader transform", () => {
  test("strips generator directives and replaces cause assignments", () => {
    const transformed =
      transformNapiLoader(generatedLoader);

    expect(transformed).not.toContain("prettier-ignore");
    expect(transformed).not.toContain("eslint-disable");
    expect(transformed).not.toContain("@ts-nocheck");
    expect(transformed).toContain("const setErrorCause =");
    expect(transformed).toContain(
      "setErrorCause(error, previous)",
    );
    expect(transformNapiLoader(transformed)).toBe(
      transformed,
    );
  });

  test("rejects an unexpected generated loader", () => {
    expect(() =>
      transformNapiLoader("module.exports = {}\n"),
    ).toThrow(
      "Generated NAPI loader no longer initializes nativeBinding",
    );
  });
});
